tax.status:
.input {$status :string}
.match $status
single {{Filing status: {#b}Single{/b}}}
joint {{Filing status: {#b}Married filing jointly{/b}}}
* {{Filing status: {#b}Other{/b}}}

export.summary:
.input {$count :integer}
.match $count
one {{{#b}{$count} session{/b} from {$from :date} to {$to :date}}}
* {{{#b}{$count} sessions{/b} from {$from :date} to {$to :date}}}
